selector_to_html = {"a[href=\"#pyskyfire.regen.outer_wall.OuterWall._spline\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.outer_wall.OuterWall._spline\">\n<span class=\"sig-name descname\"><span class=\"pre\">_spline</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">kind</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.outer_wall.OuterWall.from_chamber\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.outer_wall.OuterWall.from_chamber\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_chamber</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chamber</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Measure the outer wall across every circuit of a thrust chamber.</p><p>Where circuits overlap in <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code> they are interleaved around the\ncircumference rather than stacked on top of each other, so the two\nradii combine differently. The envelope is whichever circuit reaches\nfurthest out, since that is the crest a surrounding part has to clear.\nThe equivalent radius is built from the area they jointly enclose, each\ncircuit contributing over the angle its own channels occupy \u2013 taking\nthe larger of the two would claim the whole circumference looks like\nthe deeper circuit, and taking one circuit\u2019s channel count would assume\nit had the circle to itself.</p></dd>", "a[href=\"#pyskyfire.regen.outer_wall.OuterWall.profile\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.outer_wall.OuterWall.profile\">\n<span class=\"sig-name descname\"><span class=\"pre\">profile</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">kind</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'envelope'</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">reach</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">samples</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">401</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The wall around station <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code>, ready for a manifold section.</p><p>Returns a <a class=\"reference internal\" href=\"../../ducts/half_moon/InnerProfile.html#pyskyfire.ducts.half_moon.InnerProfile\" title=\"pyskyfire.ducts.half_moon.InnerProfile\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">InnerProfile</span></code></a>: the wall\nmeasured by arc length from <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code> rather than by station, because that\nis the room a cooling-channel breakout actually has on the surface. On\na sloped wall the surface runs further than the station span does.</p></dd>", "a[href=\"#pyskyfire.regen.outer_wall.OuterWall.dr_dx\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.outer_wall.OuterWall.dr_dx\">\n<span class=\"sig-name descname\"><span class=\"pre\">dr_dx</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">kind</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'envelope'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Slope of the outer wall at <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code>.</p></dd>", "a[href=\"../contour/Contour.html#pyskyfire.regen.contour.Contour.normal_angle\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.contour.Contour.normal_angle\">\n<span class=\"sig-name descname\"><span class=\"pre\">normal_angle</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the local wall normal angle with respect to the vertical plane.</p></dd>", "a[href=\"#pyskyfire.regen.outer_wall.OuterWall._measure\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.outer_wall.OuterWall._measure\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">static</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">_measure</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">circuit</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p><code class=\"docutils literal notranslate\"><span class=\"pre\">(envelope,</span> <span class=\"pre\">equivalent,</span> <span class=\"pre\">pitch)</span></code> for one circuit at one <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code>.</p><p>The equivalent radius is normalised by the angle the circuit\u2019s own\nchannel sweeps, so it holds whether or not the circuit tiles the circle\nby itself. <code class=\"docutils literal notranslate\"><span class=\"pre\">pitch</span></code> is the total angle the circuit occupies, which is\nwhat weights it against any circuit interleaved with it.</p><p>An outer liner is added to both radii rather than folded into the swept\narea: it is a layer laid over the finished surface, so it raises the\ncrest and the mean by its own thickness.</p></dd>", "a[href=\"../../ducts/half_moon/InnerProfile.html#pyskyfire.ducts.half_moon.InnerProfile\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.half_moon.InnerProfile\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.half_moon.</span></span><span class=\"sig-name descname\"><span class=\"pre\">InnerProfile</span></span></dt><dd><p>A wall curve in the meridional plane, measured by arc length.</p><p class=\"rubric\">Notes</p><p>Build one with <a class=\"reference internal\" href=\"../../regen/outer_wall/OuterWall.html#pyskyfire.regen.outer_wall.OuterWall.profile\" title=\"pyskyfire.regen.outer_wall.OuterWall.profile\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">profile()</span></code></a> to take\nthe wall off a resolved thrust chamber, or directly to state a wall\npyskyfire did not resolve.</p></dd>", "a[href=\"#pyskyfire.regen.outer_wall.OuterWall.r\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.outer_wall.OuterWall.r\">\n<span class=\"sig-name descname\"><span class=\"pre\">r</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">kind</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'envelope'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Outer radius at <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code> [m].</p></dd>", "a[href=\"#pyskyfire.regen.outer_wall.OuterWall.normal_angle\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.outer_wall.OuterWall.normal_angle\">\n<span class=\"sig-name descname\"><span class=\"pre\">normal_angle</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">kind</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'envelope'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Signed angle of the outward normal from radial [rad].</p><p>Positive toward <code class=\"docutils literal notranslate\"><span class=\"pre\">+x</span></code>. Unlike\n<a class=\"reference internal\" href=\"../contour/Contour.html#pyskyfire.regen.contour.Contour.normal_angle\" title=\"pyskyfire.regen.contour.Contour.normal_angle\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">normal_angle()</span></code></a>, which reports an\nunsigned angle, this keeps the sign: a manifold has to know which way\nalong the axis the wall tips, not merely by how much.</p></dd>", "a[href=\"#pyskyfire-regen-outer-wall-outerwall\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.outer_wall.OuterWall<a class=\"headerlink\" href=\"#pyskyfire-regen-outer-wall-outerwall\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.regen.outer_wall.OuterWall.normal\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.outer_wall.OuterWall.normal\">\n<span class=\"sig-name descname\"><span class=\"pre\">normal</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">kind</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'envelope'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Outward unit normal in the meridional plane, as <code class=\"docutils literal notranslate\"><span class=\"pre\">(n_x,</span> <span class=\"pre\">n_r)</span></code>.</p><p>Radially outward where the wall runs parallel to the axis, and tipped\ntoward the narrowing end where it does not.</p></dd>", "a[href=\"#pyskyfire.regen.outer_wall.OuterWall.span\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.outer_wall.OuterWall.span\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">span</span></span></dt><dd><p>First and last axial station the wall is defined over [m].</p></dd>", "a[href=\"#pyskyfire.regen.outer_wall.OuterWall\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.outer_wall.OuterWall\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.outer_wall.</span></span><span class=\"sig-name descname\"><span class=\"pre\">OuterWall</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">xs</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">envelope</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">equivalent</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Outer radius of a channelled wall against axial station.</p><p class=\"rubric\">Notes</p><p>Build one with <a class=\"reference internal\" href=\"#pyskyfire.regen.outer_wall.OuterWall.from_circuit\" title=\"pyskyfire.regen.outer_wall.OuterWall.from_circuit\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">from_circuit()</span></code></a> or <a class=\"reference internal\" href=\"#pyskyfire.regen.outer_wall.OuterWall.from_chamber\" title=\"pyskyfire.regen.outer_wall.OuterWall.from_chamber\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">from_chamber()</span></code></a> rather than\ndirectly, unless the wall is being stated by hand for a part pyskyfire did\nnot resolve.</p></dd>", "a[href=\"#pyskyfire.regen.outer_wall.OuterWall.from_circuit\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.outer_wall.OuterWall.from_circuit\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_circuit</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">circuit</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Measure the outer wall of one resolved cooling circuit.</p><p>The equivalent radius is normalised by the angle the circuit\u2019s own\nchannel sweeps, so it answers \u201cwhat cylinder encloses the same area per\nradian as this roof\u201d without assuming the circuit tiles the circle by\nitself.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
